use xiom.io;

fn main() {
  let original: Int = 42;
  let doubled: Int = original * 2;
  let plus_ten: Int = doubled + 10;
  let halved: Int = plus_ten / 2;
  let magic_result: Int = halved - original;
  io.println("5");
}
